def shortestSuperstringLength(words: list[str]) -> int:
    n = len(words)
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                for k in range(min(len(words[i]), len(words[j])), 0, -1):
                    if words[i].endswith(words[j][:k]):
                        cost[i][j] = k
                        break
    dp = [[float('inf')] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = len(words[i])
    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)) or dp[mask][last] == float('inf'): continue
            for nxt in range(n):
                if not (mask & (1 << nxt)):
                    new_mask = mask | (1 << nxt)
                    new_len = dp[mask][last] + len(words[nxt]) - cost[last][nxt]
                    if new_len < dp[new_mask][nxt]:
                        dp[new_mask][nxt] = new_len
    return min(dp[(1 << n) - 1])

